#!/usr/bin/env bash
# recipes/crate-iana-time-zone-haiku--0-1-2/build.sh -- stage the iana-time-zone-haiku 0.1.2 crate as
# an entry of the cargo directory source share/cargo/crates/ (docs/rust-crates.md).
# Generated by tools/make_crate_packages.py.
set -euo pipefail
dest="${CVC_INSTALL_DIR}/share/cargo/crates/iana-time-zone-haiku-0.1.2"
mkdir -p "${dest}"
cp -R "${CVC_SOURCE_DIR}/." "${dest}/"
