# Cargo.lock checksum, which cargo compares; no per-file hashes (the bundle's
# own sha256 covers the files).
printf '{"files":{},"package":"f31827a206f56af32e590ba56d5d2d085f558508192593743f16b2306495269f"}\n' > "${dest}/.cargo-checksum.json"
